with remaining_keys as (select id from transactions intersect select id from transactions where hour(txn_time) between 9 and 17), reconciled as (select s.* from transactions s inner join remaining_keys k on s.id = k.id) select s.id, s.account_id, s.amount, s.txn_time, s.merchant, case when merchant rlike '^(Lazada|Amazon)$' then 'GROUP_A' else 'PRIORITY' end as merchant_zone, (select sum(x.amount) from transactions x where x.account_id = s.account_id) as sum_transaction_amount from reconciled s
